suggestedReproduction.reproductionCode:
const assert = require('assert');
const http = require('http');
const express = require('./');

const app = express();

app.get('/', (req, res) => {
  res.set('Transfer-Encoding', 'chunked');
  res.send('hello world');
});

const server = app.listen(0, () => {
  const port = server.address().port;
  http.get(`http://localhost:${port}/`, (res) => {
    server.close();
    try {
      assert.strictEqual(res.headers['content-length'], undefined, 'Content-Length header should not be present');
      assert.ok(res.headers['etag'], 'ETag header should be present when etag setting is enabled');
      console.log('Test passed!');
      process.exit(0);
    } catch (err) {
      console.error('Bug reproduced:', err.message);
      process.exit(1);
    }
  });
});

